// In Game.update() when state is PLAYING:
if (!this.ball.isLaunched) {
  this.ball.x = this.paddle.x + this.paddle.width / 2;
  this.ball.y = PADDLE_Y - BALL_RADIUS;
}

launch() {
  if (this.isLaunched) return;

  const angle = (Math.random() * 60 - 30) * (Math.PI / 180);  // -30° to +30°

  this.ballSpeedX = BALL_BASE_SPEED * Math.sin(angle);
  this.ballSpeedY = -BALL_BASE_SPEED * Math.cos(angle);        // always upward
  this.isLaunched = true;
}
